#!/usr/bin/env python3
"""Static bilingual adult Hindi curriculum. All new pages noindex pending owner approval."""
from pathlib import Path
import html,json,posixpath,re
R=Path(__file__).resolve().parents[1]; S=R/'site';BASE='learn/hindi/older-adults';E=lambda s:html.escape(str(s),quote=True)
STAGES=[('foundation','नींव','Foundation','First sounds, script, essential needs and polite requests.','No previous Hindi required.'),('beginner','शुरुआत','Beginner','Family, food, shopping, travel, health and daily life.','Know the script basics, numbers and common requests or use the Foundation stage.'),('intermediate','मध्यम','Intermediate','Past and future, opinions, comparisons and practical communication.','Handle everyday exchanges and read simple Hindi sentences.'),('advanced','उन्नत','Advanced','Register, complex sentences, reasoning and formal communication.','Describe experiences and plans, understand a short passage and give reasons.'),('mastery','दक्षता','Mastery','Independent reading, translation, professional communication and research.','Understand extended passages, organize arguments and write connected Hindi.')]
C=[]
for line in (R/'source/curriculum.txt').read_text().splitlines():
 if not line or line.startswith('#'):continue
 hi,en,art,rule,words,scenario,dialogue,q,a,task=line.split('|');n=len(C)+1;stage=STAGES[(n-1)//8][0];path=f'{BASE}/{stage}/chapter-{n:02}/'
 def triples(v):
  x=[s.split('~') for s in v.split(';')];assert len(x)==4 and all(len(t)==3 and all(t) for t in x);return x
 assert (S/'images'/art).is_file(),art
 C.append(dict(n=n,hi=hi,en=en,art=art,rule=rule,phrases=triples(words),scenario=scenario,dialogue=triples(dialogue),q=q,a=a,task=task,stage=stage,path=path))
assert len(C)==40
CHECKS=json.loads((R/'source/stage-checks.json').read_text());assert len(CHECKS)==5
L=[(c,j,c['path']+f'lesson-{j:02}/') for c in C for j in (1,2)]
def rel(cur,target):
 if target.startswith('https://'):return target
 if target.startswith('#'):return target
 t,sep,f=target.partition('#');x=posixpath.relpath(t.rstrip('/'),cur.rstrip('/'));return x+('/' if t.endswith('/') else '')+(sep+f if sep else '')
def link(cur,t,label,cl=''):return f'<a class="{cl}" href="{E(rel(cur,t))}">{E(label)}</a>'
def art(cur,p,alt,cl=''):return f'<img class="{cl}" src="{E(rel(cur,"images/"+p))}" alt="{E(alt)}" width="400" height="240" loading="lazy" decoding="async">'
def audio(t):return f'<button class="audio" type="button" data-say="{E(t)}" aria-label="Listen: {E(t)}"><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M3 9h4l5-4v14l-5-4H3zM15 8q5 4 0 8m3-11q8 7 0 14"/></svg></button>'
def heading(h,e):return f'<div class="section-title"><h2 lang="hi">{E(h)}</h2><span class="en" lang="en">{E(e)}</span></div>'
def phrase(t,speaker=''):
 h,r,e=t;return f'<div class="adult-phrase"><div>{f"<span class=\"speaker\">{speaker}</span>" if speaker else ""}<b lang="hi">{E(h)}</b><span class="en" lang="hi-Latn">{E(r)}</span><span class="en" lang="en">{E(e)}</span></div>{audio(h)}</div>'
def nav(cur,prev,nxt,back):return '<nav class="lesson-nav" aria-label="Lesson navigation">'+(link(cur,prev,'← पिछला · Back','btn outline') if prev else '<span></span>')+link(cur,back,'विषय-सूची · Contents','btn outline')+(link(cur,nxt,'आगे · Next →','btn primary') if nxt else link(cur,BASE+'/','सभी स्तर · All stages','btn primary'))+'</nav>'
def page(cur,hi,en,body):
 dest=S/cur/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);title=f'{hi} — {en} | EkGuru';desc=f'{en}: practical Hindi for adults and seniors. Free bilingual lessons, listening, roleplay and independent practice.'
 h=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex, follow"><title>{E(title)}</title><meta name="description" content="{E(desc)}"><link rel="canonical" href="https://ekguru.shop/{cur}"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="https://ekguru.shop/{cur}"><link rel="stylesheet" href="{rel(cur,'css/hindi-adult-reader.css')}"><script src="{rel(cur,'js/hindi-adult-reader.js')}" defer></script></head><body><a class="skip" href="#main">Skip to lesson</a><header class="top"><div class="top-inner"><a class="brand" href="https://ekguru.shop/"><span class="logo" lang="hi">ए</span> EkGuru</a><div class="top-actions">{link(cur,BASE+'/','Adult Hindi','book-link')}<button type="button" data-large aria-pressed="false" aria-label="Larger text">A+</button><button type="button" data-english aria-pressed="true" aria-label="Toggle English and Roman assistance">EN</button><button type="button" data-theme aria-label="Toggle dark mode">◐</button></div></div></header><main id="main" class="wrap"><nav class="crumb" aria-label="Breadcrumb"><a href="https://ekguru.shop/">EkGuru</a><span>›</span><a href="https://ekguru.shop/learn/">Learn</a><span>›</span><a href="https://ekguru.shop/learn/hindi/">Hindi</a><span>›</span>{link(cur,BASE+'/','Adults & seniors')}</nav>{body}</main><footer><span>EkGuru · <span lang="hi">जीवन की हिंदी</span></span><span>Free learning · <a href="https://ekguru.shop/editorial-policy/">Editorial policy</a> · <a href="https://ekguru.shop/review/">Suggest a correction</a></span></footer><div class="toast" data-toast role="status" aria-live="polite"></div></body></html>''';dest.write_text(h)
def chapter_card(cur,c):return f'<a class="chapter-card" href="{rel(cur,c["path"])}" data-search="{E(c["hi"]+" "+c["en"]+" "+" ".join(" ".join(w) for w in c["phrases"]))}"><div class="chapter-thumb">{art(cur,c["art"],c["hi"])}<span class="chapter-num">{c["n"]:02}</span></div><div><h3 lang="hi">{E(c["hi"])}</h3><span class="en">{E(c["en"])}</span><div class="tiny">2 lessons · 1 worksheet</div><span class="chapter-go">Open →</span></div></a>'
cur=BASE+'/';body=f'<section class="hero"><div><span class="kicker">ADULTS &amp; SENIORS · ZERO TO HERO</span><h1 lang="hi">जीवन की<br><em>हिंदी।</em></h1><p>Learn Hindi for real conversations, travel, family, work and independent expression. Start at your skill level, not your age.</p><div class="hero-buttons">{link(cur,L[0][2],"Start from zero →","btn gold")}<a class="btn glass" href="#stages">Choose a level</a><a class="btn glass" data-resume hidden href="{rel(cur,L[0][2])}">Resume →</a></div></div><div class="hero-art"><div class="orbit"></div><span class="float a" lang="hi">अ</span><span class="float b" lang="hi">नमस्ते</span>{art(cur,"hindi-adult/foundation.svg","Two adult learners talking over an open book","hero-book")}</div></section><div class="stats"><div><b>5</b><span>Stages</span></div><div><b>40</b><span>Chapters</span></div><div><b>80</b><span>Lessons</span></div><div><b>40</b><span>Worksheets</span></div></div><section class="progress" data-book-progress><div><b>My learning progress</b><p class="en">Saved on this device only.</p></div><progress max="80" value="0" data-progress></progress><span data-progress-count>0 / 80</span></section><p class="adult-note">Independent self-study, not a formal qualification. Hindi speech uses a device Hindi voice when available. Tap A+ for larger text, EN for translation assistance. Material is a draft pending fluent-speaker review.</p><h2 id="stages">Choose your level · <span lang="hi">अपना स्तर चुनें</span></h2><div class="adult-stage-grid">'
for i,(slug,hi,en,desc,entry) in enumerate(STAGES,1):
 body+=f'<article class="adult-stage-card">{art(cur,"hindi-adult/"+slug+".svg",en+" learning scene")}<span class="kicker">STAGE {i:02}</span><h3 lang="hi">{hi}</h3><b>{en}</b><p>{desc}</p><p class="en">{entry}</p>{link(cur,BASE+"/"+slug+"/","Open stage →","btn primary")}</article>'
body+='</div><h2 id="chapters">All chapters</h2><label class="adult-search" hidden data-search-box>Search chapters or phrases<input type="search" data-filter placeholder="Hindi, English or Roman Hindi"></label><p data-results aria-live="polite"></p><div class="chapter-grid" data-chapter-grid>'+''.join(chapter_card(cur,c) for c in C)+'</div><p class="adult-note">Prefer the school-style pathway? <a href="https://ekguru.shop/learn/hindi/">Return to all Hindi textbooks</a>. All stages are open, no age gate or account.</p>';page(cur,'जीवन की हिंदी','Adult Hindi — Zero to Hero',body)
for i,(slug,hi,en,desc,entry) in enumerate(STAGES):
 cur=f'{BASE}/{slug}/';ch=C[i*8:i*8+8];body=f'<section class="chapter-hero"><div><span class="kicker">STAGE {i+1:02} · {en}</span><h1 lang="hi">{hi}</h1><p>{desc}</p><p class="stage-entry">Entry: {entry}</p>{link(cur,ch[0]["path"]+"lesson-01/","Start lessons →","btn primary")}</div>{art(cur,"hindi-adult/"+slug+".svg",en+" learning scene")}</section><div class="adult-stage-nav">'+link(cur,BASE+'/','All stages')+link(cur,cur+'assessment/','Stage-end self-check')+'</div><div class="chapter-grid">'+''.join(chapter_card(cur,c) for c in ch)+'</div><div class="sheet-callout">'+link(cur,cur+'assessment/','Stage-end self-check →','btn primary')+'</div>';page(cur,hi,en,body)
 cur+= 'assessment/';ck=CHECKS[i];body=f'<article class="reader"><header class="reader-head"><span class="kicker">STAGE {i+1:02} · SELF-CHECK</span><h1 lang="hi">{E(ck["title"])}</h1><p>Read or listen, then answer before revealing the model.</p><button class="btn outline" data-slow type="button" aria-pressed="false">Slow audio</button></header><section class="long-reading">'+''.join(f'<div class="adult-phrase"><div><b lang="hi">{E(h)}</b><span class="en">{E(e)}</span></div>{audio(h)}</div>' for h,e in ck['text'])+'</section>'+heading('पठन-बोध','Comprehension')+''.join(f'<details class="check"><summary>{E(q)}</summary><p>{E(a)}</p></details>' for q,a in ck['questions'])+heading('स्वतंत्र अभ्यास','Independent task')+f'<div class="roleplay-prompt">{E(ck["task"])}</div><section class="rubric"><h3>Self-assessment</h3><p>Can you understand the main idea, ask for clarification, respond intelligibly and complete the independent task? Ask a fluent speaker for feedback. If you need help, revisit the relevant lessons before progressing.</p></section>'+nav(cur,ch[-1]['path']+'lesson-02/',BASE+'/'+STAGES[i+1][0]+'/' if i<4 else None,BASE+'/'+slug+'/')+'</article>';page(cur,ck['title'],en+' self-check',body)
VOWELS='अ आ इ ई उ ऊ ऋ ए ऐ ओ औ'.split();CONS=list('कखगघङचछजझञटठडढणतथदधनपफबभमयरलवशषसह');SIGNS=['','ा','ि','ी','ु','ू','ृ','े','ै','ो','ौ','ं','ः','ँ','्'];NUMBERS='शून्य एक दो तीन चार पाँच छह सात आठ नौ दस ग्यारह बारह तेरह चौदह पंद्रह सोलह सत्रह अठारह उन्नीस बीस इक्कीस बाईस तेईस चौबीस पच्चीस छब्बीस सत्ताईस अट्ठाईस उनतीस तीस इकतीस बत्तीस तैंतीस चौंतीस पैंतीस छत्तीस सैंतीस अड़तीस उनतालीस चालीस इकतालीस बयालीस तैंतालीस चवालीस पैंतालीस छियालीस सैंतालीस अड़तालीस उनचास पचास इक्यावन बावन तिरपन चौवन पचपन छप्पन सत्तावन अट्ठावन उनसठ साठ इकसठ बासठ तिरसठ चौंसठ पैंसठ छियासठ सड़सठ अड़सठ उनहत्तर सत्तर इकहत्तर बहत्तर तिहत्तर चौहत्तर पचहत्तर छिहत्तर सतहत्तर अठहत्तर उन्नासी अस्सी इक्यासी बयासी तिरासी चौरासी पचासी छियासी सतासी अट्ठासी नवासी नब्बे इक्यानवे बानवे तिरानवे चौरानवे पचानवे छियानवे सत्तानवे अट्ठानवे निन्यानवे सौ'.split();assert len(NUMBERS)==101
def letters(ls):return '<div class="chart-letters">'+''.join(f'<div><b lang="hi">{E(x)}</b>{audio(x)}</div>' for x in ls)+'</div>'
def special(n):
 if n==2:return heading('सभी स्वर','All 11 independent vowels')+letters(VOWELS)+heading('अतिरिक्त चिह्न','Additional signs, not independent vowels')+letters(['अं','अँ','अः'])
 if n==3:return heading('सभी व्यंजन','33 standard consonants')+letters(CONS)+heading('अन्य रूप','Nukta and common conjuncts')+letters(['ड़','ढ़','क़','ख़','ग़','ज़','फ़','क्ष','त्र','ज्ञ','श्र'])
 if n==4:return heading('मात्रा प्रयोग','Vowel-sign builder')+'<div class="visual-model"><label>Consonant <select data-base>'+''.join(f'<option>{x}</option>' for x in CONS)+'</select></label><div class="model-choices">'+''.join(f'<button type="button" data-matra="{s}">{E("क"+s)}</button>' for s in SIGNS)+'</div><p class="model-parts"><span data-matra-display>क</span><button type="button" data-matra-audio class="btn outline">Listen</button></p><details><summary>All 33 × 13 traditional practice forms</summary><div class="reading">'+''.join('<p lang="hi">'+' · '.join(c+s for s in SIGNS[:13])+'</p>' for c in CONS)+'</div></details></div>'
 if n==5:return heading('० से १००','Numbers 0–100')+letters([f'{i} · {w}' for i,w in enumerate(NUMBERS)])
 if n==6:return heading('सप्ताह के दिन','Days of the week')+letters('सोमवार मंगलवार बुधवार गुरुवार शुक्रवार शनिवार रविवार'.split())
 return ''
def quiz(stem,opts,correct):return f'<div class="check" data-quiz><h3>{E(stem)}</h3><div class="choices">'+''.join(f'<button type="button" data-correct="{str(x==correct).lower()}">{E(x)}</button>' for x in opts)+f'</div><p data-feedback aria-live="polite"></p><details><summary>Answer</summary><p>{E(correct)}</p></details></div>'
def workspace(id,task):return f'<section class="writing-workspace" data-writing-workspace="{id}"><label for="draft">{E(task)}</label><textarea id="draft" data-draft rows="5" maxlength="16000" placeholder="अपना उत्तर लिखें / Write your answer"></textarea><div class="draft-actions"><span data-word-count aria-live="polite">0 शब्द</span><button type="button" class="btn outline" data-save-draft>Save on this device</button><button type="button" class="btn outline" data-clear-draft>Delete draft</button></div><p data-draft-status role="status"></p><small>Use fictional or non-sensitive details. No server submission or automatic scoring.</small></section>'
for c in C:
 n=c['n'];cur=c['path'];stagepath=BASE+'/'+c['stage']+'/';body=f'<section class="chapter-hero"><div><span class="kicker">CHAPTER {n:02} · {c["stage"].upper()}</span><h1 lang="hi">{E(c["hi"])}</h1><p>{E(c["en"])}</p><p>{E(c["scenario"])}</p></div>{art(cur,c["art"],c["hi"])}</section><div class="lesson-grid">'+''.join(f'<a class="chapter-card" href="{rel(cur,c["path"]+f"lesson-{j:02}/")}"><div><h3>{label}</h3><p>{desc}</p></div></a>' for j,label,desc in [(1,'01 · Learn the language','Understand the pattern, listen and practise useful phrases.'),(2,'02 · Use it in conversation','Read the dialogue, roleplay and complete a new task.')])+'</div><div class="sheet-callout">'+link(cur,cur+'worksheet/','Printable worksheet →','btn primary')+'</div>'+nav(cur,C[n-2]['path'] if n>1 else None,C[n]['path'] if n<40 else stagepath+'assessment/',stagepath);page(cur,c['hi'],c['en'],body)
 for j in (1,2):
  cur=c['path']+f'lesson-{j:02}/';idx=(n-1)*2+j-1;id=f'adult-{n:02}-{j:02}';stagech=[x for x in C if x['stage']==c['stage']];body=f'<div class="reader-layout"><aside class="reader-side"><span class="kicker">{c["stage"].upper()}</span><b>Chapter navigation</b><div class="toc">'+''.join(link(cur,x['path'],f'{x["n"]:02} · {x["hi"]}','current' if x==c else '') for x in stagech)+f'</div>{link(cur,stagepath,"Stage contents →")}</aside><article class="reader"><header class="reader-head"><span class="kicker">CHAPTER {n:02} / LESSON {j:02}</span><h1 lang="hi">{E(c["hi"])}</h1><p>{E(c["en"])} · {"Learn the pattern" if j==1 else "Use it in conversation"}</p><div class="reader-tools"><button type="button" class="btn primary" data-say="{E("। ".join(x[0] for x in (c["phrases"] if j==1 else c["dialogue"])))}">▶ Listen to all</button><button type="button" class="btn outline" data-slow aria-pressed="false">Slow audio</button><button type="button" class="btn outline" data-stop>Stop</button></div><small>Device Hindi voice required; not a native recording.</small></header><figure class="context-figure">{art(cur,c["art"],c["hi"])}<figcaption>{E(c["scenario"])}</figcaption></figure>'
  if j==1:
   body+=heading('भाषा समझें','Understand the pattern')+f'<div class="concept-box en"><p>{E(c["rule"])}</p></div>'+heading('उपयोगी वाक्य','Useful phrases')+''.join(phrase(t) for t in c['phrases'])+special(n)
   for k,t in enumerate(c['phrases'][:2]):
    opts=[x[0] for x in c['phrases']];opts=opts[(n+k)%4:]+opts[:(n+k)%4];body+=quiz('Which phrase means: '+t[2],opts,t[0])
   body+=heading('लिखें','Copy and read aloud')+f'<div class="copy-board"><div class="copy-model" lang="hi">{E(c["phrases"][0][0])}</div><div class="copy-model ghost" lang="hi">{E(c["phrases"][1][0])}</div><div class="copy-line"></div></div><div class="draw-pad"><canvas width="720" height="230" data-draw aria-label="Freehand writing practice"></canvas><div><button type="button" class="btn outline" data-undo>Undo</button> <button type="button" class="btn outline" data-clear>Clear</button></div><small>Freehand practice, not verified stroke-order instruction.</small></div>'
  else:
   body+=heading('बातचीत','Listen and roleplay')+'<div class="dialogue">'+''.join(phrase(t,'A' if k%2==0 else 'B') for k,t in enumerate(c['dialogue']))+'</div>'+heading('समझ जाँचें','Check understanding')+f'<details class="check"><summary>{E(c["q"])}</summary><p>{E(c["a"])}</p></details>'+quiz('Which reply follows the first line of this model dialogue?',[c['dialogue'][3][0],c['dialogue'][1][0],c['dialogue'][2][0]],c['dialogue'][1][0])+heading('स्वतंत्र अभ्यास','Transfer to a new situation')+f'<div class="roleplay-prompt"><p>Read both roles. Then cover the English, take role B and respond aloud. Change the details for a new conversation.</p><p>{E(c["task"])}</p></div>'+workspace(id,c['task'])
  nextpath=L[idx+1][2] if idx<79 else None
  if j==2 and n%8==0:nextpath=stagepath+'assessment/'
  body+=f'<div class="finish"><button type="button" class="btn primary" data-complete="{id}">✓ पाठ पूरा किया</button>{link(cur,c["path"]+"worksheet/","Worksheet","btn outline")}<p class="en">Completion is self-marked and stored locally.</p></div>'+nav(cur,L[idx-1][2] if idx else None,nextpath,c['path'])+'</article></div>';page(cur,c['hi'],c['en']+f' — Lesson {j}',body)
 cur=c['path']+'worksheet/';body=f'<section class="worksheet adult-worksheet"><header class="reader-head"><span class="kicker">CHAPTER {n:02} · WORKSHEET</span><h1 lang="hi">{E(c["hi"])}</h1><p>{E(c["en"])}</p><div class="print-tools"><button type="button" data-print class="btn primary">Print / Save PDF</button><button type="button" data-ink class="btn outline" aria-pressed="false">Ink-saving</button></div></header><p>Name: ____________________ Date: ____________</p><section class="worksheet-part"><h2>1. Write the Hindi phrase</h2>'+''.join(f'<p>{E(t[2])}</p><div class="blank"></div>' for t in c['phrases'])+'</section><section class="worksheet-part"><h2>2. Respond to the situation</h2><p>'+E(c['scenario'])+'</p><p lang="hi">'+E(c['dialogue'][0][0])+'</p><div class="blank"></div><p>'+E(c['q'])+'</p><div class="blank"></div><h2>3. Independent task</h2><p>'+E(c['task'])+'</p><div class="blank"></div><div class="blank"></div></section><details class="answer-key"><summary>Model answers (open before printing if needed)</summary>'+''.join(f'<p lang="hi">{E(t[0])} — {E(t[2])}</p>' for t in c['phrases'])+f'<p>Model reply: {E(c["dialogue"][1][0])}</p><p>{E(c["a"])}</p><p>Independent response varies; review accuracy, clarity and appropriateness.</p></details></section>'+nav(cur,None,c['path']+'lesson-02/',c['path']);page(cur,c['hi']+' — कार्यपत्रक',c['en']+' worksheet',body)
manifest={'version':1,'id':'adult-hindi','status':'draft-review-required','root':BASE,'stages':[{'id':x[0],'hi':x[1],'en':x[2],'entry':x[4],'chapters':[c for c in C if c['stage']==x[0]],'assessment':CHECKS[i]} for i,x in enumerate(STAGES)]};(S/'data/learning/hindi-adult-book.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n');print(f'{len(C)} chapters, {len(L)} lessons, 5 stage assessments, {len(list((S/BASE).rglob("index.html")))} pages')
